<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {demoMode,request} from '@/services/quality'
import AppModal from '@/components/AppModal.vue'
const route=useRoute();const router=useRouter();const mode=computed(()=>route.path.includes('google-callback')?'google':route.path.includes('verify-email')?'verify':route.path.includes('reset-password')?'reset':'forgot')
const params=new URLSearchParams(window.location.hash.slice(1));const token=ref(params.get('token')||'');const code=ref(params.get('code')||'');const purpose=params.get('purpose')||'verify';const error=ref(params.has('error')?'La connexion Google n’a pas abouti. Connectez-vous par email ou associez votre compte depuis Sécurité.':'');const notice=ref('');const busy=ref(false);const open=ref(false);const email=ref('');const password=ref('');const confirmation=ref('');const mfa=ref('')
// Remove secrets from the current URL and browser history once captured.
onMounted(()=>{if(window.location.hash)history.replaceState(null,'',window.location.pathname)})
const titles={forgot:'Mot de passe oublié',reset:'Renouveler mon mot de passe',verify:'Vérifier mon email',google:'Terminer la connexion Google'}
async function submit(){busy.value=true;error.value='';try{if(demoMode)throw new Error('Ce parcours nécessite l’aperçu API.');if(mode.value==='forgot'){notice.value=(await request<{message:string}>('/auth/forgot-password','POST',{email:email.value})).message}
else if(mode.value==='verify'){await request('/auth/email/verify','POST',{token:token.value,purpose});notice.value='Adresse vérifiée. Vous pouvez reprendre votre dossier ou vous reconnecter.';token.value=''}
else if(mode.value==='reset'){await request('/auth/reset-password','POST',{token:token.value,password:password.value,password_confirmation:confirmation.value,mfa_code:mfa.value||undefined});sessionStorage.clear();notice.value='Mot de passe renouvelé. Toutes les sessions ont été révoquées.';token.value='';password.value='';confirmation.value=''}
else {const d=await request<{token:string;is_platform_admin:boolean;mfa_enrollment_required?:boolean}>('/auth/google/exchange','POST',{code:code.value,mfa_code:mfa.value||undefined});sessionStorage.removeItem('bestpharma.officine');sessionStorage.setItem('bestpharma.token',d.token);sessionStorage.setItem('bestpharma.platform',String(d.is_platform_admin));router.push(d.mfa_enrollment_required?'/dashboard/securite':d.is_platform_admin?'/beg/inscriptions':'/choose-officine')}
open.value=false}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
</script>
<template><div class="registration-page"><header><RouterLink to="/login" class="brand">bestpharma.</RouterLink><RouterLink to="/login" class="text-link">Connexion</RouterLink></header><section class="registration-content"><p class="eyebrow">SÉCURITÉ DU COMPTE</p><h1>{{titles[mode]}}</h1><p v-if="notice" class="alert success" role="status">{{notice}}</p><p v-if="error&&!open" class="alert error" role="alert">{{error}}</p><p class="page-subtitle">Les liens sont temporaires et utilisables une seule fois. Une vérification ne donne pas accès à une officine non approuvée.</p><button v-if="!notice" class="button primary" style="margin-top:24px" :disabled="demoMode" @click="open=true">{{mode==='forgot'?'Demander un lien':mode==='google'?'Continuer':'Ouvrir la vérification'}}</button><RouterLink v-if="notice" :to="mode==='verify'?'/application':'/login'" class="button primary">{{mode==='verify'?'Reprendre mon dossier':'Se connecter'}}</RouterLink><p v-if="demoMode" class="module-disclaimer">Fonction disponible en mode API uniquement.</p></section><AppModal v-model="open" :title="titles[mode]" :busy="busy"><form id="recovery-form" class="form-body correction-form" @submit.prevent="submit"><p v-if="error" class="alert error" role="alert">{{error}}</p><label v-if="mode==='forgot'">Adresse email<input v-model="email" type="email" required maxlength="254" autocomplete="email"/></label><template v-else-if="mode==='reset'"><label>Nouveau mot de passe<input v-model="password" type="password" required minlength="12" maxlength="128" autocomplete="new-password"/></label><label>Confirmation<input v-model="confirmation" type="password" required minlength="12" maxlength="128" autocomplete="new-password"/></label></template><label v-if="mode==='reset'||mode==='google'">Code MFA ou code de secours (si activé)<input v-model="mfa" inputmode="text" maxlength="32" autocomplete="one-time-code"/></label><p v-if="mode==='verify'">Confirmez l’utilisation de ce lien pour vérifier l’adresse destinataire.</p></form><template #footer><button :disabled="busy" class="button secondary" @click="open=false">Annuler</button><button :disabled="busy" class="button primary" form="recovery-form" type="submit">Confirmer</button></template></AppModal></div></template>
